(()=>{
 const panel=document.querySelector('#import-panel');let job=null,running=false,stop=false,loaded=false;
 const safe=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const cats=['Hatch','SUV','Sedã','Monovolume','Picape','Perua','Cupê','Outro'],gears=['Automático','Manual','Automatizado','CVT'],fuels=['Flex','Gasolina','Diesel','Elétrico','Híbrido','Consultar'];
 const labels={brand:'Marca',name:'Modelo',version:'Versão',price:'Preço (R$)',year:'Ano do modelo',km:'Quilometragem',category:'Categoria',transmission:'Câmbio',fuel:'Combustível',badge:'Etiqueta',description:'Descrição'};
 const statuses={review:'Revisar',pending:'Na fila',copying:'Copiando fotos',completed:'Publicado',error:'Precisa de atenção',skipped:'Ignorado'};
 const message=(text,focus=false)=>{const el=panel.querySelector('#import-message');el.textContent=text;if(focus){el.tabIndex=-1;el.focus({preventScroll:true});el.scrollIntoView({block:'center'})}};
 const field=(key,value)=>{const options=key==='category'?cats:key==='transmission'?gears:key==='fuel'?fuels:null;return `<label>${labels[key]}${options?`<select data-field="${key}"><option value="">Selecionar</option>${options.map(v=>`<option ${v===value?'selected':''}>${safe(v)}</option>`).join('')}</select>`:key==='description'?`<textarea data-field="${key}" maxlength="3000" rows="3">${safe(value)}</textarea>`:`<input data-field="${key}" value="${safe(value)}" ${['price','year','km'].includes(key)?`type="number" step="${key==='price'?'0.01':'1'}" min="${key==='price'?'0.01':key==='year'?'1900':'0'}"`:'type="text" maxlength="120"'}>`}</label>`};
 function render(){
  const review=job?.status==='review',selected=job?.rows.filter(r=>r.selected)||[],done=selected.filter(r=>r.status==='completed').length,totalPhotos=selected.reduce((a,r)=>a+r.photoCount,0),copied=selected.reduce((a,r)=>a+r.copied.length,0);
  panel.innerHTML=`<div class="import-intro"><div><span class="eyebrow brand">MIGRAÇÃO DE ESTOQUE</span><h2>Do WooCommerce para sua garagem.</h2><p>Traga os dados do catálogo e copie as fotos para o armazenamento da loja.</p></div><span class="import-format">CSV → ESTOQUE</span></div>
   <div class="import-steps" aria-label="Etapas da importação"><span class="${!job?'active':''}"><b>01</b> Enviar CSV</span><span class="${review?'active':''}"><b>02</b> Revisar veículos</span><span class="${job&&!review?'active':''}"><b>03</b> Copiar e publicar</span></div>
   <div class="import-upload"><div><strong>Exportação de produtos do WooCommerce</strong><p>CSV UTF-8 · até 1 MB · até 500 veículos. Preços promocionais não são importados.</p></div><label class="button outline small">${job?'Carregar outro CSV':'Selecionar arquivo CSV'}<input type="file" id="woo-file" accept=".csv,text/csv" class="sr-only" ${running?'disabled':''}></label></div>
   <p class="import-note">As fotos são baixadas e copiadas para o Vercel Blob. Cada veículo só aparece no site com todas as fotos copiadas. Faça a importação antes de alterar o domínio do WordPress.</p>
   <p id="import-message" role="alert"></p>
   ${job?`<div class="import-summary"><div><span>ARQUIVO EM REVISÃO</span><strong>${safe(job.filename)}</strong></div><div><b>${job.rows.length}</b><span>veículos no CSV</span></div><div><b>${job.rows.filter(r=>r.targetId).length}</b><span>já cadastrados</span></div><div><b>${job.rows.reduce((a,r)=>a+r.photoCount,0)}</b><span>fotos encontradas</span></div></div>
   ${review?`<div class="import-toolbar"><p>Confira os dados abaixo. Veículos já cadastrados vêm desmarcados; selecioná-los substitui seus dados e fotos.</p><div><button type="button" class="text-link" data-select="new">Selecionar novos</button><button type="button" class="text-link" data-select="none">Desmarcar todos</button></div></div>`:`<div class="import-progress" role="status"><div><strong>${job.status==='completed'?'Importação finalizada':running?'Copiando fotos para o Blob…':'Importação pausada — pronta para retomar'}</strong><span>${done} de ${selected.length} veículos publicados · ${copied} de ${totalPhotos} fotos</span></div><progress max="${Math.max(totalPhotos,1)}" value="${copied}" aria-label="Fotos copiadas"></progress><p>O progresso fica salvo. Você pode pausar ou voltar a este painel para continuar.</p></div>`}
   <div class="import-rows">${job.rows.map(row=>`<article class="import-row ${row.status==='error'?'has-error':''}" data-source="${safe(row.sourceId)}"><div class="import-row-head">${review?`<input type="checkbox" data-select-row ${row.selected?'checked':''} ${!row.eligible?'disabled':''} aria-label="Importar ${safe(row.title)}">`:`<span class="import-row-number">${row.status==='completed'?'✓':safe(row.sourceId)}</span>`}<div><h3>${safe(row.title)}</h3><p>ID ${safe(row.sourceId)} · ${row.photoCount} fotos${row.targetId?' · Cadastro existente':''}</p></div><span class="import-status">${safe(statuses[row.status])}</span></div>
   ${row.warnings.length?`<ul class="import-warnings">${row.warnings.map(w=>`<li>${safe(w)}</li>`).join('')}</ul>`:''}
   ${row.error?`<p class="import-error" role="alert">${safe(row.error)}</p>`:''}
   ${review?`<details ${row.selected&&(!row.candidate.transmission||row.candidate.km===null||!row.candidate.version)?'open':''}><summary>Conferir e editar dados <span>${safe(row.candidate.year||'Ano pendente')} · ${row.candidate.km===null?'KM pendente':new Intl.NumberFormat('pt-BR').format(row.candidate.km)+' km'} · ${safe(row.candidate.category)}</span></summary><div class="import-fields">${Object.keys(labels).map(k=>field(k,row.candidate[k])).join('')}</div></details>`:`<p class="import-row-progress">${row.copied.length} / ${row.photoCount} fotos copiadas${row.status==='completed'?` · <a href="/veiculo/${safe(row.targetId)}" target="_blank" rel="noopener">Ver anúncio ↗</a>`:''}</p>`}</article>`).join('')}</div>
   <div class="import-actions">${review?`<label class="import-ack"><input type="checkbox" id="import-ack">Revisei os veículos selecionados, incluindo os avisos, e autorizo publicar os dados e copiar as fotos.</label><button class="button dark" id="woo-start">Importar selecionados ↗</button>`:job.status!=='completed'?`<button class="button ${running?'outline':'dark'}" id="woo-resume">${running?'Pausar após esta foto':'Retomar importação ↗'}</button>`:`<p>Estoque atualizado. Os anúncios publicados usam apenas fotos copiadas para o armazenamento da loja.</p>`}</div>`:''}`;
  panel.querySelector('#woo-file').onchange=readFile;
  panel.querySelectorAll('[data-select]').forEach(button=>button.onclick=()=>{collect();job.rows.forEach(r=>r.selected=button.dataset.select==='new'&&r.eligible&&!r.targetId);render()});
  panel.querySelector('#woo-start')?.addEventListener('click',start);
  panel.querySelector('#woo-resume')?.addEventListener('click',()=>{if(running){stop=true;message('Pausando após concluir a foto atual…')}else run()});
 }
 function collect(){panel.querySelectorAll('[data-source]').forEach(el=>{const row=job.rows.find(r=>r.sourceId===el.dataset.source);row.selected=!!el.querySelector('[data-select-row]')?.checked;el.querySelectorAll('[data-field]').forEach(input=>row.candidate[input.dataset.field]=['price','year','km'].includes(input.dataset.field)?input.value===''?null:Number(input.value):input.value.trim())})}
 async function readFile(event){const file=event.target.files[0];if(!file)return;event.target.disabled=true;message('Lendo e validando o CSV…');try{if(file.size>1024*1024)throw Error('O CSV deve ter até 1 MB.');const csv=new TextDecoder('utf-8',{fatal:true}).decode(await file.arrayBuffer());job=await api('admin/imports',{method:'POST',body:JSON.stringify({csv,filename:file.name})});render();message('CSV lido. Confira os avisos e os dados antes de importar.')}catch(e){message(e.message);event.target.disabled=false;event.target.value=''}}
 async function start(){if(!panel.querySelector('#import-ack').checked){message('Confirme a revisão antes de importar.',true);return}collect();const rows=job.rows.map(r=>({sourceId:r.sourceId,selected:r.selected,...(r.selected?{candidate:r.candidate}:{})}));panel.querySelector('#woo-start').disabled=true;try{job=await api(`admin/imports/${job.id}/start`,{method:'POST',body:JSON.stringify({rows})});await run()}catch(e){message(e.message,true);panel.querySelector('#woo-start')&&(panel.querySelector('#woo-start').disabled=false)}}
 async function run(){if(running)return;running=true;stop=false;render();try{while(!stop&&job.status!=='completed'){job=await api(`admin/imports/${job.id}/step`,{method:'POST',body:'{}'});render();if(job.status==='paused')break}await loadDashboard()}catch(e){message(e.message)}finally{const error=panel.querySelector('#import-message')?.textContent;running=false;render();if(error)message(error)}}
 window.gasparImporter={open:async()=>{if(loaded||running)return;loaded=true;render();try{job=await api('admin/imports');render()}catch(e){loaded=false;message(e.message)}}};render();
})();
